                    mService = new Messenger(service);
                    Toast.makeText(MainActivity.this, "onServiceConnected", Toast.LENGTH_SHORT).show();
                    try {
                        service.linkToDeath(mDeathRecipient, 0);
                    } catch (RemoteException e) {
                        Log.d(TAG, "linkToDeath", e);
