    public void test2() {
        ObjectAnimator animator = ObjectAnimator.ofInt(mView, BACKGROUND_ALPHA, 10);
        animator.setInterpolator(ALPHA_INTERPOLATOR);
        animator.setDuration(2000);
        animator.start();
    }
PropertyValuesHolder
