            // 显示状态栏和导航栏
            getWindow().getDecorView().getWindowInsetsController().show(WindowInsets.Type.systemBars());
        }else{
            getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_VISIBLE);
        }
